// uploads-smart: Worker API created from org-baseline (worker-api template).
// PUT /files/:name stores the request body in R2; only callers with the
// shared API key may upload. GET /files/:name returns the stored bytes.
// Every upload is summarized in one sentence via the org AI Gateway.

interface Env {
	AI: Ai;
	UPLOADS: R2Bucket;
	/** Shared upload key, set via `wrangler secret put API_KEY` (or .dev.vars). */
	API_KEY: string;
}

/** Every model call goes through the org AI Gateway with git.next cost metadata. */
function gateway(task: string) {
	return { gateway: { id: "git-next", metadata: { repo: "uploads-smart", agent: "app", task } } };
}

function objectKey(name: string): string {
	return `uploads-smart/${name}`;
}

function isAuthorized(request: Request, env: Env): boolean {
	const header = request.headers.get("Authorization") ?? "";
	const token = header.startsWith("Bearer ") ? header.slice(7) : "";
	return !!env.API_KEY && token === env.API_KEY;
}

async function describeUpload(env: Env, name: string, contentType: string, bytes: ArrayBuffer): Promise<string> {
	let sample: string;
	try {
		sample = new TextDecoder("utf-8", { fatal: true }).decode(bytes.slice(0, 4000));
	} catch {
		sample = `[binary content, ${bytes.byteLength} bytes]`;
	}
	const prompt =
		`File name: ${name}\nContent-Type: ${contentType}\nSize: ${bytes.byteLength} bytes\n` +
		`Content sample:\n${sample}\n\nWrite exactly one sentence describing this file.`;
	try {
		const result = await env.AI.run(
			"@cf/zai-org/glm-5.3-flash",
			{ messages: [{ role: "user", content: prompt }] },
			gateway("describe-upload"),
		);
		const text = (result as { response?: string }).response?.trim();
		return text && text.length > 0 ? text : "A file was uploaded.";
	} catch {
		return "A file was uploaded, but a description could not be generated.";
	}
}

export default {
	async fetch(request: Request, env: Env): Promise<Response> {
		const url = new URL(request.url);
		if (url.pathname === "/health") return Response.json({ ok: true });

		const match = url.pathname.match(/^\/files\/([^/]+)$/);
		if (!match) return new Response("Not found", { status: 404 });
		const name = decodeURIComponent(match[1]);
		const key = objectKey(name);

		if (request.method === "PUT") {
			if (!isAuthorized(request, env)) {
				return Response.json({ error: "unauthorized" }, { status: 401 });
			}
			const bytes = await request.arrayBuffer();
			const contentType = request.headers.get("Content-Type") ?? "application/octet-stream";
			const description = await describeUpload(env, name, contentType, bytes);
			await env.UPLOADS.put(key, bytes, {
				httpMetadata: { contentType },
				customMetadata: { description },
			});
			return Response.json({ name, size: bytes.byteLength, contentType, description });
		}

		if (request.method === "GET") {
			const object = await env.UPLOADS.get(key);
			if (!object) return new Response("Not found", { status: 404 });
			const headers = new Headers();
			object.writeHttpMetadata(headers);
			if (object.customMetadata?.description) {
				headers.set("X-Description", object.customMetadata.description);
			}
			return new Response(object.body, { headers });
		}

		return new Response("Method not allowed", { status: 405 });
	},
} satisfies ExportedHandler<Env>;

wrangler.jsonc:
{
	// Generated by `git next new` from org-baseline. Secrets go in `wrangler secret put NAME` (or .dev.vars locally), never here.
	"$schema": "node_modules/wrangler/config-schema.json",
	"name": "uploads-smart",
	"main": "src/index.ts",
	"compatibility_date": "2026-10-06",
	"compatibility_flags": ["nodejs_compat"],
	"observability": { "enabled": true },
	// Workers AI only through the org gateway: pass { gateway: { id: "git-next" } } on every env.AI.run call.
	"ai": { "binding": "AI" },
	// Shared bucket from the org catalog; keys are namespaced as uploads-smart/<name>.
	"r2_buckets": [{ "binding": "UPLOADS", "bucket_name": "acme-shared-uploads" }]
	// Add only resources from .gitnext/catalog.json. Forks must not bind production resources.
}
